INSERT INTO `tbl_customer_oc` (`id`, `customer_id`, `quotation_id`, `main_quotation_id`, `po_descriptions`, `oc_referance`, `purchase_order_no`, `purchase_order_date`, `ga_drawing_no`, `proforma_order_no`, `proforma_invoice_date`, `header_body_message`, `footer_body_message`, `subject`, `created_at`, `created_by`, `updated_at`, `updated_by`, `deleted_by`, `deleted_at`) VALUES
(1, 2, 5, 1, '1', '<ol><li>po. attch ref</li><li>asd wer uyu 123</li></ol>', 'qwe', '2024-05-27', 'qw', 'q123', '2024-05-29', '<p>&nbsp;</p><p>Dear Sir/Madam,</p><p>We thankfully acknowledge receipt of your<strong> Purchase Order No. dtd. </strong>received thro’ email and request to please courier signed hard copy of the</p><p>same for our ISO mandatory compliance</p><p>In reference to above, we’re accepting your order in general &amp; are going ahead for the production of ENCON make high efficiency energy saving E-Glass Epoxy FRP Fan for your Air Fin Cooler while assuring you to dispatch the same on or before 20 th February’ 2024 as per the delivery schedule. However, we will make all possible sincere efforts to up–date the supplies from our end and will keep you posted accordingly</p><h2>&nbsp;</h2>', '<p>In reference to above, we’re accepting your order in general &amp; are going ahead for the production of ENCON make high efficiency energy saving E-Glass Epoxy FRP Fan for your Air Fin Cooler while assuring you to dispatch the same on or before 20 th February’ 2024 as per the delivery schedule. However, we will make all possible sincere efforts to up–date the supplies from our end and will keep you posted accordingly</p><p>Dear Sir/Madam,</p><p>We thankfully acknowledge receipt of your<strong> Purchase Order No. dtd. </strong>received thro’ email and request to please courier signed hard copy of the</p><p>same for our ISO mandatory compliance</p><h2>&nbsp;</h2><p>Please find enclosed our G<strong>A Drawing No. EE/GA/SMEL/23-24/661 </strong>and kindly send your approval with stamp &amp; signature immediately to process the production and timely dispatch of material at the earliest</p>', '1', '2024-05-27 16:32:02', 1, NULL, NULL, NULL, NULL);
INSERT INTO `tbl_customer_quotation` (`id`, `customer_id`, `company_id`, `order_no`, `order_sequence`, `amendment_main_quotation_id`, `amendment_sequences`, `commercial`, `roiDescription`, `quotation_status`, `referance`, `subject`, `estimated_date`, `expiry_date`, `approved_by`, `approved_at`, `quotation_invoice_pdf_name`, `created_at`, `created_by`, `updated_at`, `updated_by`, `deleted_by`, `deleted_at`) VALUES
(1, 2, 3, 'EFFPL/CE-RK/JSW/195/8', 8, NULL, NULL, '<p>Dear Sir,<br>We thank you for the kind courtesy extended during the visit our Service Engineer<br><strong>Mr. Rakesh Dalvi &amp; Mr. Lakshmi Narasimhan </strong>at your site on 28 th August’ 2023.<br>In reference to joint performance testing of your existing ACC Fan, we’re pleased to submit our<br>techno-commercial offer for the supply of ENCON make high efficiency energy saving<br>E-Glass Epoxy FRP Fan for replacement of your existing ACC Fan as under.</p>', '<p>Please note that you’ll be recovering minimum capital saving of Rs. 55,63,950/= per year<br>which will consolidate to the tune of Rs. 2,78,19,750/= in five years after the installation of<br>our ENCON aerodynamically designed energy efficient FRP Fan against confirmed power<br>reduction guarantee of 20% after the replacement</p>', 0, 'Facebook', 'SUPPLY OF ENCON MAKE HIGH EFFICIENCY ENERGY SAVING E-GLASS EPOXY FRP FAN FOR YOUR GREENESOL MAKE AIR COOLED CONDENSOR', '2024-05-27', '2026-06-08', NULL, NULL, NULL, '2024-05-27 15:55:28', 1, NULL, NULL, NULL, NULL),
(4, 1, 2, 'EFFPL/CE-RK/JSW/226/1', 1, NULL, NULL, '<p>Dear Sir,<br>We thank you for the kind courtesy extended during the visit our Service Engineer<br>Mr. Rakesh Dalvi &amp; Mr. Lakshmi Narasimhan at your site on 28 th August’ 2023.<br>In reference to joint performance testing of your existing ACC Fan, we’re pleased to submit our<br>techno-commercial offer for the supply of ENCON make high efficiency energy saving<br>E-Glass Epoxy FRP Fan for replacement of your existing ACC Fan as under.</p>', '<p>Please note that you’ll be recovering minimum capital saving of Rs. 55,63,950/= per year<br>which will consolidate to the tune of Rs. 2,78,19,750/= in five years after the installation of<br>our ENCON aerodynamically designed energy efficient FRP Fan against confirmed power<br>reduction guarantee of 20% after the replacement.</p>', 0, 'qwe', 'SUPPLY OF ENCON MAKE HIGH EFFICIENCY ENERGY SAVING E-GLASS EPOXY FRP FAN FOR YOUR GREENESOL MAKE AIR COOLED CONDENSOR', '2024-05-27', '2024-05-27', NULL, NULL, NULL, '2024-05-27 16:27:00', 1, NULL, NULL, NULL, NULL),
(5, 2, 3, 'EFFPL/CE-RK/JSW/195/8-1', 9, 1, 1, '<p>Dear Sir,<br>We thank you for the kind courtesy extended during the visit our Service Engineer<br><strong>Mr. Rakesh Dalvi &amp; Mr. Lakshmi Narasimhan </strong>at your site on 28 th August’ 2023.<br>In reference to joint performance testing of your existing ACC Fan, we’re pleased to submit our<br>techno-commercial offer for the supply of ENCON make high efficiency energy saving<br>E-Glass Epoxy FRP Fan for replacement of your existing ACC Fan as under.</p>', '<p>Please note that you’ll be recovering minimum capital saving of Rs. 55,63,950/= per year<br>which will consolidate to the tune of Rs. 2,78,19,750/= in five years after the installation of<br>our ENCON aerodynamically designed energy efficient FRP Fan against confirmed power<br>reduction guarantee of 20% after the replacement</p>', 0, 'Facebook', 'SUPPLY OF ENCON MAKE HIGH EFFICIENCY ENERGY SAVING E-GLASS EPOXY FRP FAN FOR YOUR GREENESOL MAKE AIR COOLED CONDENSOR', '2024-05-27', '2026-06-08', NULL, NULL, NULL, '2024-05-27 16:29:56', 1, NULL, NULL, NULL, NULL);
INSERT INTO `tbl_customer_quotation_footer_note` (`id`, `quotation_id`, `master_footer_note_id`, `technical_title`, `technical_description`, `created_at`, `created_by`, `updated_at`, `updated_by`, `deleted_by`, `deleted_at`) VALUES
(1, 1, 4, 'Warranty', '<ul><li>The material supplied by us will be guaranteed for a period of 18 months from the date of dispatch or 12 months from the date of commissioning, whichever is earlier, against any manufacturing defects.</li><li>The&nbsp;above warranty is void if the material supplied is subject&nbsp;to abuse or service in excess of its design limitations. Notice&nbsp; of&nbsp; the&nbsp; defects&nbsp; must&nbsp; be&nbsp; given&nbsp; promptly&nbsp; after&nbsp; its discovery; otherwise, this warranty is void.</li></ul>', '2024-05-27 15:55:28', 1, NULL, NULL, NULL, NULL),
(2, 1, 7, 'Transportation', '<p>Through your nominated transportation agency on freight to-pay basic.</p>', '2024-05-27 15:55:28', 1, NULL, NULL, NULL, NULL),
(3, 1, 3, 'Terms of Payment', '<ol><li><strong>FOR TRIAL SUPPLY: </strong>100% Within 15 days of successful installation achieving the guaranteed energy saving.</li><li><strong>FOR&nbsp; BALANCE&nbsp; SUPPLY:&nbsp; </strong>90%&nbsp; Against&nbsp; delivery&nbsp; &amp;&nbsp; 10% Within&nbsp; 15&nbsp; days&nbsp; of&nbsp; installation&nbsp; or&nbsp; 30&nbsp; days&nbsp; of&nbsp; delivery, whichever&nbsp;is earlier</li></ol>', '2024-05-27 15:55:28', 1, NULL, NULL, NULL, NULL),
(4, 1, 6, 'Taxes', '<p>IGST @18% will be applicable as you can avail 100% set off as per the GST directives.</p>', '2024-05-27 15:55:28', 1, NULL, NULL, NULL, NULL),
(5, 1, 9, 'Prices', '<p>The prices quoted above are based on Ex-Works basis.</p>', '2024-05-27 15:55:28', 1, NULL, NULL, NULL, NULL),
(6, 1, 8, 'P and F Charges', '<p>@3.6% for quality environment friendly wooden packing to avoid any transit damage from our works to your site.</p>', '2024-05-27 15:55:28', 1, NULL, NULL, NULL, NULL),
(7, 1, 2, 'Notes', '<ol><li><p style=\"text-align:justify;\">You will provide Free Lodging and Boarding for our visiting&nbsp;&nbsp; Engineer&nbsp; along&nbsp; with&nbsp;&nbsp; technician&nbsp; at&nbsp;&nbsp; your Guest House during the installation support&nbsp; period of&nbsp; FRP&nbsp; Fan.&nbsp; You&nbsp; will&nbsp; also&nbsp; provide&nbsp; “to&nbsp; and&nbsp; fro” transport&nbsp; conveyance&nbsp; from&nbsp; the&nbsp; nearest&nbsp; Railway Station&nbsp; for&nbsp; our&nbsp; visiting&nbsp; Service&nbsp; Engineer&nbsp; to&nbsp; reach your site.</p></li><li><p style=\"text-align:justify;\">Please&nbsp; find&nbsp; enclosed&nbsp; various&nbsp; credentials&nbsp; of&nbsp; similar supplies&nbsp;replacements for your ready reference.</p></li></ol>', '2024-05-27 15:55:28', 1, NULL, NULL, NULL, NULL),
(8, 1, 1, 'Delivery Period', '<p>Our offer is valid for the period of 30 days from to–date.</p>', '2024-05-27 15:55:28', 1, NULL, NULL, NULL, NULL),
(9, 1, 5, 'Delivery Period', '<ol><li><strong>FOR TRIAL SUPPLY</strong>: We confirm to dispatch 01 Set within 4 to 5 week from date of receipt of firm order.</li><li><strong>FOR&nbsp; BALANCE&nbsp; SUPPLY:&nbsp; </strong>The&nbsp; balance&nbsp; quantity&nbsp; will&nbsp; be dispatched&nbsp; within&nbsp; 9&nbsp; to&nbsp; 14&nbsp; week&nbsp; after&nbsp; receipt&nbsp; of&nbsp; your&nbsp; firm order, clear in all respects.</li></ol>', '2024-05-27 15:55:28', 1, NULL, NULL, NULL, NULL),
(10, 2, 0, NULL, '<ul><li>The material supplied by us will be guaranteed for a period of 18 months from the date of dispatch or 12 months from the date of commissioning, whichever is earlier, against any manufacturing defects.</li><li>The&nbsp;above warranty is void if the material supplied is subject&nbsp;to abuse or service in excess of its design limitations. Notice&nbsp; of&nbsp; the&nbsp; defects&nbsp; must&nbsp; be&nbsp; given&nbsp; promptly&nbsp; after&nbsp; its discovery; otherwise, this warranty is void.</li></ul>', '2024-05-27 15:55:51', 1, NULL, NULL, 1, '2024-05-27 15:56:34'),
(11, 2, 1, 'Delivery Period', '<p>Through your nominated transportation agency on freight to-pay basic.</p>', '2024-05-27 15:55:51', 1, NULL, NULL, 1, '2024-05-27 15:56:34'),
(12, 2, 2, 'Notes', '<ol><li><strong>FOR TRIAL SUPPLY: </strong>100% Within 15 days of successful installation achieving the guaranteed energy saving.</li><li><strong>FOR&nbsp; BALANCE&nbsp; SUPPLY:&nbsp; </strong>90%&nbsp; Against&nbsp; delivery&nbsp; &amp;&nbsp; 10% Within&nbsp; 15&nbsp; days&nbsp; of&nbsp; installation&nbsp; or&nbsp; 30&nbsp; days&nbsp; of&nbsp; delivery, whichever&nbsp;is earlier</li></ol>', '2024-05-27 15:55:51', 1, NULL, NULL, 1, '2024-05-27 15:56:34'),
(13, 2, 3, 'Terms of Payment', '<p>IGST @18% will be applicable as you can avail 100% set off as per the GST directives.</p>', '2024-05-27 15:55:51', 1, NULL, NULL, 1, '2024-05-27 15:56:34'),
(14, 2, 4, 'Warranty', '<p>The prices quoted above are based on Ex-Works basis.</p>', '2024-05-27 15:55:51', 1, NULL, NULL, 1, '2024-05-27 15:56:34'),
(15, 2, 5, 'Delivery Period', '<p>@3.6% for quality environment friendly wooden packing to avoid any transit damage from our works to your site.</p>', '2024-05-27 15:55:51', 1, NULL, NULL, 1, '2024-05-27 15:56:34'),
