INSERT INTO `tbl_master_footer_notes` (`id`, `title`, `description`, `created_at`, `created_by`, `updated_at`, `updated_by`, `deleted_by`, `deleted_at`) VALUES
(1, 'Delivery Period', '<p>Our offer is valid for the period of 30 days from to–date.</p>', '2024-05-15 11:57:20', 1, '2024-05-15 11:57:20', NULL, NULL, '2024-05-15 11:57:20'),
(2, 'Notes', '<ol><li><p style=\'text-align:justify;\'>You will provide Free Lodging and Boarding for our visiting&nbsp;&nbsp; Engineer&nbsp; along&nbsp; with&nbsp;&nbsp; technician&nbsp; at&nbsp;&nbsp; your Guest House during the installation support&nbsp; period of&nbsp; FRP&nbsp; Fan.&nbsp; You&nbsp; will&nbsp; also&nbsp; provide&nbsp; “to&nbsp; and&nbsp; fro” transport&nbsp; conveyance&nbsp; from&nbsp; the&nbsp; nearest&nbsp; Railway Station&nbsp; for&nbsp; our&nbsp; visiting&nbsp; Service&nbsp; Engineer&nbsp; to&nbsp; reach your site.</p></li><li><p style=\'text-align:justify;\'>Please&nbsp; find&nbsp; enclosed&nbsp; various&nbsp; credentials&nbsp; of&nbsp; similar supplies&nbsp;replacements for your ready reference.</p></li></ol>', '2024-05-15 11:57:20', 1, '2024-05-15 11:57:20', NULL, NULL, '2024-05-15 11:57:20'),
(3, 'Terms of Payment', '<ol><li><span class=\'ck-list-bogus-paragraph\'><strong>FOR TRIAL SUPPLY: </strong>100% Within 15 days of successful installation achieving the guaranteed energy saving.</span></li><li><span class=\'ck-list-bogus-paragraph\'><strong>FOR&nbsp; BALANCE&nbsp; SUPPLY:&nbsp; </strong>90%&nbsp; Against&nbsp; delivery&nbsp; &amp;&nbsp; 10% Within&nbsp; 15&nbsp; days&nbsp; of&nbsp; installation&nbsp; or&nbsp; 30&nbsp; days&nbsp; of&nbsp; delivery, whichever&nbsp;is earlier</span></li></ol>', '2024-05-15 11:57:20', 1, '2024-05-15 11:57:20', NULL, NULL, '2024-05-15 11:57:20'),
(4, 'Warranty', '<ul><li><span class=\'ck-list-bogus-paragraph\'>The material supplied by us will be guaranteed for a period of 18 months from the date of dispatch or 12 months from the date of commissioning, whichever is earlier, against any manufacturing defects.</span></li><li><span class=\'ck-list-bogus-paragraph\'>The&nbsp;above warranty is void if the material supplied is subject&nbsp;to abuse or service in excess of its design limitations. Notice&nbsp; of&nbsp; the&nbsp; defects&nbsp; must&nbsp; be&nbsp; given&nbsp; promptly&nbsp; after&nbsp; its discovery; otherwise, this warranty is void.</span></li></ul>', '2024-05-21 08:50:31', 0, '2024-05-21 08:50:31', NULL, NULL, '2024-05-21 08:50:31'),
(5, 'Delivery Period', ' <ol><li><span class=\'ck-list-bogus-paragraph\'><strong>FOR TRIAL SUPPLY</strong>: We confirm to dispatch 01 Set within 4 to 5 week from date of receipt of firm order.</span></li><li><span class=\'ck-list-bogus-paragraph\'><strong>FOR&nbsp; BALANCE&nbsp; SUPPLY:&nbsp; </strong>The&nbsp; balance&nbsp; quantity&nbsp; will&nbsp; be dispatched&nbsp; within&nbsp; 9&nbsp; to&nbsp; 14&nbsp; week&nbsp; after&nbsp; receipt&nbsp; of&nbsp; your&nbsp; firm order, clear in all respects.</span></li></ol>', '2024-05-21 08:50:31', 0, '2024-05-21 08:50:31', NULL, NULL, '2024-05-21 08:50:31'),
(6, 'Taxes', '<p> IGST @18% will be applicable as you can avail 100% set off as per the GST directives.</p>', '2024-05-21 08:50:31', 0, '2024-05-21 08:50:31', NULL, NULL, '2024-05-21 08:50:31'),
(7, 'Transportation', '<p>Through your nominated transportation agency on freight to-pay basic.</p>', '2024-05-21 08:50:31', 0, '2024-05-21 08:50:31', NULL, NULL, '2024-05-21 08:50:31'),
(8, 'P and F Charges', '<p>@3.6% for quality environment friendly wooden packing to avoid any transit damage from our works to your site.</p>', '2024-05-21 08:50:31', 0, '2024-05-21 08:50:31', NULL, NULL, '2024-05-21 08:50:31'),
(9, 'Prices', '<p>The prices quoted above are based on Ex-Works basis.</p>', '2024-05-21 08:50:31', 0, '2024-05-21 08:50:31', NULL, NULL, '2024-05-21 08:50:31');
